-- Step 1: Create index (run once)
CREATE EXTENSION IF NOT EXISTS pg_trgm;

CREATE INDEX idx_keyword_keyword ON keyword(keyword);
CREATE INDEX idx_title_production_year ON title(production_year);
CREATE INDEX idx_title_title_trgm ON title USING gin (title gin_trgm_ops);
CREATE INDEX idx_company_name_name_trgm ON company_name USING gin (name gin_trgm_ops);
CREATE INDEX idx_mc_partial_note_null ON movie_companies (movie_id, company_id, company_type_id) WHERE note IS NULL;
CREATE INDEX idx_mk_movie_id_keyword_id ON movie_keyword (movie_id, keyword_id);
CREATE INDEX idx_ml_movie_id_link_type_id ON movie_link (movie_id, link_type_id);

-- Step 2: Run the optimized query
SELECT MIN(cn.name) AS from_company,
       MIN(lt.link) AS movie_link_type,
       MIN(t.title) AS sequel_movie
FROM title AS t
INNER JOIN movie_keyword AS mk ON t.id = mk.movie_id
INNER JOIN keyword AS k ON k.id = mk.keyword_id
INNER JOIN movie_companies AS mc ON t.id = mc.movie_id
INNER JOIN company_name AS cn ON cn.id = mc.company_id
INNER JOIN company_type AS ct ON ct.id = mc.company_type_id
INNER JOIN movie_link AS ml ON t.id = ml.movie_id
INNER JOIN link_type AS lt ON lt.id = ml.link_type_id
WHERE t.production_year = 1998
  AND t.title LIKE '%Money%'
  AND k.keyword = 'sequel'
  AND mc.note IS NULL
  AND ct.kind = 'production companies'
  AND cn.country_code != '[pl]'
  AND (cn.name LIKE '%Film%' OR cn.name LIKE '%Warner%')
  AND lt.link LIKE '%follows%';
